# Lesson 3 of MKTG90037: service-dominant logic (Week 4). Brand: Hilton (10-K facts). Instrument: goods logic to service logic
# (Connect). Ends movement 1.
from mk import *  # noqa: F403


def L03(CID):
    SK = 'mk.service-logic'
    left = [dict(id='g1', label=T('Making something', '制造东西')), dict(id='g2', label=T('Goods are valuable', '商品本身有价值')), dict(id='g3', label=T('Value is produced', '价值是生产出来的')),
            dict(id='g4', label=T('Customers are isolated buyers', '顾客是孤立的买家')), dict(id='g5', label=T('Customers are targets', '顾客是目标')), dict(id='g6', label=T('Unit of analysis: the product', '分析单位：产品'))]
    right = [dict(id='s1', label=T('Helping the customer create value', '帮顾客创造价值')), dict(id='s2', label=T('Goods render a service', '商品提供的是服务')), dict(id='s3', label=T('Value is co-created, in use', '价值是共同创造的，在使用中')),
             dict(id='s4', label=T('Customers sit in a network', '顾客处在一个网络里')), dict(id='s5', label=T('Customers are resources', '顾客是资源')), dict(id='s6', label=T('Unit of analysis: the relationship', '分析单位：关系'))]
    pairs = [['g1', 's1', T('Goods logic is about what the firm makes; service logic about assisting what the customer does.', '商品逻辑看企业做出什么；服务逻辑看帮顾客做成什么。')],
             ['g2', 's2', T('A drill is not wanted for itself but for the hole it makes: goods are appliances for service.', '没人要钻机本身，要的是它打出的洞：商品是提供服务的工具。')],
             ['g3', 's3', T('There is no value until an offering is used: experience and perception decide it.', '产品被使用之前没有价值：由体验和感知决定。')],
             ['g4', 's4', T('Customers live among other people and resources, not alone.', '顾客生活在其他人和资源之中，不是孤立的。')],
             ['g5', 's5', T('A target is aimed at; a resource brings skills and effort that help create the value.', '目标是被瞄准的；资源带来技能和努力，帮助创造价值。')],
             ['g6', 's6', T('The thing to analyse moves from the output to the connection between firm and customer.', '分析的对象从产出转到企业和顾客之间的联系。')]]
    return dict(
        id=f'{CID}-service-logic',
        title=T('Who creates the value: the factory or the customer?', '谁创造价值：工厂，还是顾客？'),
        description=T('Where value is created, in the hotel or in the guest’s stay, and the service-dominant logic that follows, with Hilton.', '价值是在酒店里创造的，还是在客人的住宿体验里创造的？由此引出服务主导逻辑，案例是 Hilton。'),
        minutes=35,
        skills=[{'id': SK, 'name': T('Explaining and applying service-dominant logic', '解释并应用服务主导逻辑')}],
        misconceptions=[
            {'id': 'sd-only-services', 'description': T('service-dominant logic only applies to service businesses', '服务主导逻辑只适用于服务业')},
            {'id': 'firm-delivers-value', 'description': T('the firm can deliver value to the customer like a parcel', '企业可以像递包裹一样把价值递给顾客')},
        ],
        steps=[
            read('puzzle', T('Where is the value of a night in a hotel?', '一晚酒店的价值在哪里？'),
                 p(T("Hilton says its founder wanted “to fill the earth with the light and warmth of hospitality”. A guest books a room. When does the value of that stay come into being: when the hotel was built, when the room was cleaned, or when the guest sleeps there, uses the shower, scrolls the app and feels looked after?",
                     "Hilton 说它的创始人想“用热情好客的光和暖，充满整个地球”。一位客人订了一间房。这次住宿的价值是什么时候产生的：酒店建成时、房间打扫好时，还是客人住进去、用淋浴、刷应用、觉得被照顾的时候？")),
                 chapter=CH['puzzle']),
            predict('guess', SK, T("When does the value of the stay exist?", "住宿的价值是什么时候存在的？"),
                    [(T("When the guest uses the room and experiences the stay", "客人使用房间、体验住宿的时候"), True),
                     (T("When the hotel is built: value is built into the hotel", "酒店建成的时候：价值被造进了酒店"), T("An empty, perfect room is worth nothing to anyone until somebody uses it.", "一间再完美的空房间，没人用就对谁都没价值。")),
                     (T("When the guest pays", "客人付钱的时候"), T("Paying is an exchange. The value the guest gets comes later, in use.", "付钱只是交换。客人得到的价值在后面，在使用中。")),
                     (T("When the brand is advertised", "品牌做广告的时候"), T("An advert promises; it is not the value itself.", "广告只是承诺，不是价值本身。"))],
                    T("In use. That one move, from value-in-exchange to **value-in-use**, is the whole of service-dominant logic. Now match the old picture to the new.", "在使用中。从“交换价值”转到**使用价值**，就是服务主导逻辑的全部。现在把旧图景和新图景一一对上。")),
            read('touch', T('Old picture, new picture', '旧图景，新图景'),
                 p(T("Goods logic and service logic describe the same six things in opposite ways.", "商品逻辑和服务逻辑对同样六件事，说法正好相反。")),
                 connect(T('Six statements of goods logic on the left; connect each to its service-logic counterpart on the right.', '左边六条商品逻辑的说法；把每一条连到右边对应的服务逻辑说法。'), left, right, pairs, no=T('Not a counterpart. Ask what each side says about who does the creating.', '不是对应的一对。想想各自对“谁来创造”怎么说。'),
                         done=T("Every pair is the same move: from **the firm makes value and delivers it** to **the customer, with the firm’s help, creates value in use**.", "每一对都是同一个转变：从**企业造出价值并交付**到**顾客在企业的帮助下，在使用中创造价值**。"), height=860),
                 chapter=CH['touch']),
            read('name', T('The framework, as the marker wants it', '阅卷人要的框架'),
                 p(T("**Service-dominant (S-D) logic** (Vargo and Lusch) says the customer is always a **co-creator of value**. Customers are not passive consumers; they bring skills and knowledge (**operant resources**) and use goods as **appliances** in their own value-creating processes. Four ideas to be able to state:",
                     "**服务主导（S-D）逻辑**（Vargo 和 Lusch）认为顾客永远是**价值的共同创造者**。顾客不是被动的消费者；他们带来技能和知识（**操作性资源**），把商品当作自己创造价值过程中的**工具**。要能说出的四点：")),
                 ol(T("The application of skills and knowledge is the fundamental unit of exchange: **service is exchanged for service**.", "运用技能和知识是交换的基本单位：**用服务换服务**。"),
                    T("Goods are distribution mechanisms for service provision: “activities render service; things render service” (Gummesson).", "商品是提供服务的分发机制：“活动提供服务；东西也提供服务”（Gummesson）。"),
                    T("The customer is always a co-creator of value.", "顾客永远是价值的共同创造者。"),
                    T("There is **no value until an offering is used**: experience and perception decide it.", "产品被使用之前**没有价值**：由体验和感知决定。")),
                 p(T("Grönroos pushes it further: “companies don’t deliver value, customers do.” The firm makes **value propositions** and resources available; value is created in the customer’s **value-in-use**, and only some stages of it (the ones where the firm and customer interact directly) are truly *co-creation*. Under goods logic the unit of analysis is the output; under service logic it is **the relationship or connectivity**, and the orientation moves from the producer to the consumer.",
                     "Grönroos 说得更进一步：“企业不交付价值，顾客才创造价值。”企业提供**价值主张**和资源；价值在顾客的**使用价值**里创造，其中只有企业和顾客直接互动的阶段才是真正的*共同创造*。商品逻辑下，分析单位是产出；服务逻辑下是**关系或连接**，导向也从生产者转向消费者。")),
                 chapter=CH['name']),
            apply_q('apply', SK, T("Use Hilton (the 2025 report: 243 million Hilton Honors members; most hotels owned and run by others under its brands). Write four sentences: what Hilton provides as resources, where the value is created, and one reason this is not just “a hotel company is a service business”.",
                              "以 Hilton 为例（2025 年报：2.43 亿 Hilton Honors 会员；多数酒店由他人在其品牌下拥有并经营）。写四句话：Hilton 提供了哪些资源，价值在哪里创造，以及为什么这不只是“酒店公司属于服务业”。"),
                    [T("Names resources Hilton provides: brand, standards, booking and Honors, hotels run by owners and staff", "点出 Hilton 提供的资源：品牌、标准、预订与 Honors、由业主和员工运营的酒店"),
                     T("Says value arises in the guest’s use of the stay, and the guest contributes (booking, preferences, using the app, feedback)", "说明价值在客人使用住宿时产生，客人也有贡献（预订、偏好、用应用、反馈）"),
                     T("Uses a true fact (243 million Honors members, franchised hotels, points-and-money options)", "用一条真实事实（2.43 亿 Honors 会员、特许酒店、积分加现金选项）"),
                     T("Explains that S-D logic is a view of value creation, not a label for service industries", "说明 S-D 逻辑是看待价值创造的角度，而不是服务业的标签")],
                    T("Hilton provides resources rather than finished value: a brand and standards, hotels run by owners or managers, a booking system and the Honors programme with 243 million members. Value arises when a guest uses them, so the guest co-creates it by choosing the stay, using points and the app and giving feedback, which is value-in-use. Because most Hilton hotels are franchised, the value of a stay depends on owners and their staff acting on Hilton’s standards, which shows value is created across a network, not delivered by one firm. S-D logic is not about service industries: a car or a toilet roll is also an appliance for the customer’s own value creation.",
                      "Hilton 提供的是资源而不是现成的价值：品牌和标准、由业主或管理者运营的酒店、预订系统和拥有 2.43 亿会员的 Honors 计划。客人使用这些资源时价值才产生，客人通过选择住宿、用积分和应用、给反馈来共同创造价值，这就是使用价值。因为 Hilton 的多数酒店是特许经营，一次住宿的价值取决于业主和员工按 Hilton 标准行事，说明价值是在网络里创造的，而不是由一家企业交付的。S-D 逻辑并不只关于服务业：汽车或卷纸同样是顾客创造自己价值的工具。"),
                    T("Say what the company provides and where the customer’s own activity is.", "要说清公司提供了什么，以及顾客自己的活动在哪里。")),
            choice('neighbour', T('The look-alike', '长得像的那个'), SK,
                   T("“Service-dominant logic means firms should focus on services, not goods.” What is wrong with that?", "“服务主导逻辑意思是企业应该多做服务、少做商品。”这句话错在哪？"),
                   [(T("It is a way of seeing all offerings: goods too are appliances through which customers get a service", "它是看待所有产品的方式：商品也是顾客获得服务的工具"), True),
                    (T("Nothing: it favours services over goods", "没错：它偏向服务而非商品"), T("S-D logic is not a product-mix recommendation; it is a view of where value comes from.", "S-D 逻辑不是产品组合建议，而是对价值来源的看法。")),
                    (T("It should say goods only", "应该说只做商品"), T("That is goods logic.", "那是商品逻辑。"))],
                   T("The word “dominant” is about the logic, not the industry.", "“主导”说的是逻辑，不是行业。"), purpose='check', chapter=CH['neighbour']),
            recall('r1', SK, T("From lesson 2: the Post-it started as a glue nobody asked for. This is a case of what?", "来自第 2 课：便利贴起初是没人要的胶。这是什么情形？"),
                   [(T("A latent need that a market-oriented firm pursued", "一个市场导向的企业追求的潜在需求"), True), (T("A customer-led success", "顾客牵着走的成功"), T("No customer had asked for it.", "没有顾客提过。"))],
                   T("Latent needs are what customers cannot yet say.", "潜在需求就是顾客还说不出的需求。"), first=True),
            recall('r2', SK, T("From lesson 1: which meaning of “value” fits value-in-use best?", "来自第 1 课：“价值”的哪个含义最贴近使用价值？"),
                   [(T("What I get for what I give, in my own situation", "在我自己的情境里，我付出多少、得到多少"), True), (T("A low price", "低价"), T("Price is only part of what is given.", "价格只是付出的一部分。"))],
                   T("Value is perceived and relative, so it is realised in use.", "价值是感知的、相对的，所以在使用中实现。")),
        ] + exam_three('exam', SK,
                       T("Question. (a) Explain service-dominant logic and how it differs from goods-dominant logic. (b) Apply it to Hilton Hotels in Australia. (c) Make two recommendations.",
                         "题目。(a) 解释服务主导逻辑及其与商品主导逻辑的区别。(b) 把它应用到澳大利亚的 Hilton 酒店。(c) 给出两条建议。"),
                       (T("Write the **Explain** part.", "写**解释**部分。"),
                        [T("Customer is always a co-creator of value; value is created in use", "顾客永远是价值的共同创造者；价值在使用中创造"),
                         T("Goods are appliances or distribution mechanisms for service", "商品是服务的工具/分发机制"),
                         T("Contrast: goods logic sees value produced by the firm and the customer as target; service logic sees value co-created and the customer as resource", "对比：商品逻辑认为价值由企业生产、顾客是目标；服务逻辑认为价值共同创造、顾客是资源"),
                         T("Unit of analysis moves from the output to the relationship", "分析单位从产出转到关系")],
                        T("Service-dominant logic (Vargo and Lusch) holds that the customer is always a co-creator of value and that value exists only in use. Goods are not valuable in themselves; they are appliances, or distribution mechanisms, through which skills and knowledge are applied as service. Under goods logic value is produced by the firm and customers are targets; under service logic value is co-created and customers are resources in a network. The unit of analysis therefore moves from the output to the relationship between firm and customer. Grönroos adds that firms offer value propositions but customers create value-in-use.",
                          "服务主导逻辑（Vargo 和 Lusch）认为顾客永远是价值的共同创造者，价值只存在于使用之中。商品本身没有价值；它们是把技能和知识作为服务来运用的工具或分发机制。商品逻辑下，价值由企业生产，顾客是目标；服务逻辑下，价值共同创造，顾客是网络中的资源。所以分析单位从产出转到企业与顾客之间的关系。Grönroos 补充说，企业提供价值主张，价值在顾客的使用中创造。")),
                       (T("Write the **Apply** part.", "写**应用**部分。"),
                        [T("Names what Hilton provides as resources: brand, standards, hotels, booking, Honors programme", "点出 Hilton 提供的资源：品牌、标准、酒店、预订、Honors 计划"),
                         T("Uses a verified Hilton fact such as 243 million Honors members at the end of 2025 or that most hotels are franchised", "用经核实的 Hilton 事实，如 2025 年底 2.43 亿 Honors 会员或多数酒店为特许经营"),
                         T("Shows the guest co-creating value in use, and the network of owners and staff", "说明客人在使用中共同创造价值，以及业主和员工构成的网络"),
                         T("Explains cause and effect for the firm’s relationship focus (why Honors, standards, franchise support matter)", "解释企业为何关注关系（Honors、标准、特许支持为什么重要）")],
                        T("Hilton offers resources, not finished value. At the end of 2025 about 8,239 of its properties were franchised against 873 managed and 46 owned, so most stays are produced by owners and their staff working to Hilton brand standards. The guest co-creates value in use: choosing the hotel, using Honors points, the points-and-money option and free Wi-Fi for members, and giving feedback. Honors had 243 million members, which makes the relationship, not a single room, the thing Hilton manages, because members return and each booking through Hilton’s channels gives it direct contact. Value therefore depends on the network: a franchisee’s lapse hurts the guest’s value-in-use and Hilton’s brand, so standards and support are central.",
                          "Hilton 提供资源，而不是现成的价值。2025 年底，约 8,239 家物业是特许经营，873 家受托管理，46 家自有，所以多数住宿由业主和员工按 Hilton 品牌标准来完成。客人在使用中共同创造价值：选酒店、用 Honors 积分、积分加现金选项和会员免费 Wi-Fi、给反馈。Honors 有 2.43 亿会员，使关系而非单间客房成为 Hilton 经营的对象，因为会员会回头，每次通过 Hilton 渠道预订都让它与客人有直接联系。价值因此取决于网络：加盟商的疏漏会伤害客人的使用价值和 Hilton 的品牌，所以标准和支持至关重要。")),
                       (T("Write the **Recommend** part: exactly two.", "写**建议**部分：恰好两条。"),
                        [T("Exactly two, from the analysis (for example strengthen franchise standards support, or give guests more ways to shape their stay)", "恰好两条，从分析里推出（如加强特许经营标准支持，或让客人更多参与塑造住宿）"),
                         T("Each actionable", "每条可执行"), T("Names a risk, such as owner cost or complexity", "点出风险，如业主成本或复杂度")],
                        T("First, give franchisees shared service-training and quality audits tied to Honors guest feedback, because the analysis showed franchised hotels produce most of the value-in-use. The risk is cost to owners, so support should be shared. Second, let Honors members shape the stay before arrival, choosing room features and services in the app, because guests co-create value and the relationship is Hilton’s direct asset. The risk is operational complexity for hotels, so start with a few options.",
                          "第一，为加盟商提供共享的服务培训和质量审核，并与 Honors 客人反馈挂钩，因为分析表明特许酒店创造了多数使用价值。风险是业主的成本，所以支持应该分摊。第二，让 Honors 会员在入住前就能塑造住宿，在应用里选择房间特点和服务，因为客人共同创造价值，而这份关系是 Hilton 的直接资产。风险是酒店运营更复杂，所以先从少数选项开始。")),
                       ),
    )
